head.script:
scwin.onpageload = function() {
    requires("uiplugin.popup");
    var options = {
        id: "common_message135206914",
        type: "wframePopup",
        width: "1080px",
        height: "600px",
        top: "120px",
        left: "220px",
        popupName: "testPopup2",
        modal: true,
        resizable: true,
        status: true,
        menubar: false,
        scrollbars: false,
        title: false,
        dataObject: {
            "type": "json",
            "data": {
                "data": {
                    "msgType": "alert",
                    "msgStr": "조건을 입력하세요",
                    "etcStr": ""
                },
                "callbackFn": "mf_pop1134557335_wframe_scwin.closeCallbackFnc",
                "callbackFnObj": "",
                "objPre": "mf_pop1134557335_wframe_",
                "popupID": "mf_pop1134557335_wframe_common_message135206914"
            },
            "name": "param"
        }
    };
    $p.openPopup("gridView_autofit_popup_WEFF-826_(WSQ-4178)_sub.xml", options);
};
scwin.onpageunload = function() {};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#common_message135206914_wframe_gridViewPopup1').height() > 95", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
